// HELP ILLUSTRATIONS — a picture of each option in the vocabularies a person has to choose from.
//
// User directive, 2026-08-30: *"the text can be initially generated by you, but the images should be
// editable by the sbg admin. for packaging, truck bodies, equipment and cargo nature."*
//
// The four lists this covers are the ones where the right answer is RECOGNISED rather than known. A shop
// clerk can see that a load is on pallets; they may not know the word "palletised", and they certainly
// cannot tell a skeletal from a curtain-side by name. A picture settles in one glance what a paragraph
// argues about — and it survives a reader who does not read well, which is the same reason every sheet in
// this product carries a ReadAloud.
//
// WHY THE ADMIN OWNS THE IMAGES. A drawing of "a flatbed" is a claim about what trucks look like HERE. The
// vehicle that means "flatbed" in Nakuru is not the one a European stock photo shows, and the deployment
// that knows which is which is the deployment, not this repository. Same reasoning as DEFAULT_PACKAGING:
// the network ships the vocabulary, the deployment supplies the local truth.
//
// The TEXT deliberately does not live here. It stays in the frontend i18n catalogs, because every string in
// this product is a translatable key (the i18n epic) and a database column is not translatable.

import { PACKAGING } from './packaging';
import { TRUCK_SUBTYPES } from './fleet.config';
import { CARGO_NATURES, EQUIPMENT } from './cargo.types';

/** The four vocabularies an admin can illustrate. */
export const HELP_TOPICS = ['packaging', 'body', 'equipment', 'nature'] as const;
export type HelpTopic = (typeof HELP_TOPICS)[number];

/**
 * The valid option keys per topic — READ FROM THE CANONICAL LISTS, never copied.
 *
 * This is the whole reason an illustration cannot outlive the thing it illustrates: add a truck subtype and
 * it appears in the admin grid waiting for a picture; remove one and its key stops validating. A hand-kept
 * second list would let an admin curate an option the system no longer has.
 */
export const HELP_TOPIC_KEYS: Record<HelpTopic, readonly string[]> = {
  packaging: PACKAGING,
  body: TRUCK_SUBTYPES,
  equipment: EQUIPMENT,
  nature: CARGO_NATURES,
};

/** Is this a real option of this topic? Guards the admin write path against a key nothing can ever show. */
export function isHelpKey(topic: HelpTopic, key: string): boolean {
  return HELP_TOPIC_KEYS[topic]?.includes(key) ?? false;
}

export function isHelpTopic(v: unknown): v is HelpTopic {
  return typeof v === 'string' && (HELP_TOPICS as readonly string[]).includes(v);
}

/**
 * One curated illustration.
 *
 * Note what is NOT here: no owner, no retention class, no expiry. Every other image in this system is
 * somebody's private evidence on a clock (a delivery photo, a KYC document) and the whole MediaService
 * design is built to expire it. A help illustration is the opposite of that in all three respects — it is
 * published, it belongs to the network, and it must still be there in a year — so it is deliberately a
 * separate rail rather than a MediaKind with three exemptions bolted on. Exemptions are how a private-photo
 * store springs a leak.
 */
export interface HelpImage {
  topic: HelpTopic;
  key: string;
  /** The blob key holding the bytes. Rotated on every replace, so a cache can never serve the old picture. */
  blobId: string;
  contentType: string;
  size: number;
  /** Who last changed it, for the audit line an operator action deserves. */
  updatedBy: string;
  updatedAt: string;
}

/** What a picker needs to render its help: which options have a picture, and where to get it. */
export interface HelpOptionView {
  key: string;
  /** Absent when no admin has uploaded one yet — the sheet then shows text alone, never a broken frame. */
  imageUrl?: string;
  updatedAt?: string;
}

export interface HelpTopicView {
  topic: HelpTopic;
  options: HelpOptionView[];
}

/**
 * A help illustration is a diagram, not a photograph — it should be small. Well under the 500 KB a delivery
 * photo is allowed, because this one is fetched by every clerk on every booking over a phone connection
 * somebody is paying for by the megabyte.
 */
export const HELP_IMAGE_MAX_BYTES = 150 * 1024;
